from shop.errors import ValidationError


class Coupon:
    def __init__(self, code, kind, value):
        if not code:
            raise ValidationError("Coupon code must be non-empty")
        if kind not in ("percent", "fixed"):
            raise ValidationError("Coupon kind must be 'percent' or 'fixed'")
        if kind == "percent" and (value < 0 or value > 100):
            raise ValidationError("Percent discount must be between 0 and 100")
        if kind == "fixed" and value < 0:
            raise ValidationError("Fixed discount must be non-negative")

        self.code = code
        self.kind = kind
        self.value = value

    def discount_for(self, subtotal_cents):
        if self.kind == "percent":
            discount = round(subtotal_cents * self.value / 100)
        else:  # fixed
            discount = min(self.value, subtotal_cents)

        return max(0, discount)
